        PriorityQueue<Integer> minHeap = new PriorityQueue<>((a, b) -> count.get(a) - count.get(b));
        for (int num : count.keySet()) {
            minHeap.add(num);
            if (minHeap.size() > k) minHeap.poll();
        }
        int[] res = new int[k];
        for (int i = 0; i < k; i++) res[i] = minHeap.poll();
        return res;
    }
