class MedianFinder {
    constructor() {
        this.nums = [];
    }
    addNum(num) {
        // Binary search insertion for javascript array
        let low = 0, high = this.nums.length;
        while (low < high) {
            let mid = (low + high) >> 1;
            if (this.nums[mid] < num) low = mid + 1;
            else high = mid;
        }
        this.nums.splice(low, 0, num);
    }
    findMedian() {
        const n = this.nums.length;
        const mid = Math.floor(n / 2);
        if (n % 2 !== 0) return this.nums[mid];
        return (this.nums[mid - 1] + this.nums[mid]) / 2.0;
    }
}

