std::vector<int> mergeKSortedArrays(std::vector<std::vector<int>>& arrays) {
    using Element = std::tuple<int, int, int>; // val, arr_idx, elem_idx
    std::priority_queue<Element, std::vector<Element>, std::greater<Element>> minHeap;
    for (int i = 0; i < arrays.size(); i++) {
        if (!arrays[i].empty()) {
            minHeap.push({arrays[i][0], i, 0});
        }
    }
    std::vector<int> result;
    while (!minHeap.empty()) {
        auto [val, arrIdx, elemIdx] = minHeap.top(); minHeap.pop();
        result.push_back(val);
        if (elemIdx + 1 < arrays[arrIdx].size()) {
            minHeap.push({arrays[arrIdx][elemIdx + 1], arrIdx, elemIdx + 1});
        }
    }
    return result;
}

