public class MergeKSortedArrays {
    static class Element {
        int val, arrIdx, elemIdx;
        Element(int v, int a, int e) { val = v; arrIdx = a; elemIdx = e; }
    }
    public static List<Integer> mergeKSortedArrays(int[][] arrays) {
        PriorityQueue<Element> minHeap = new PriorityQueue<>((a, b) -> a.val - b.val);
        for (int i = 0; i < arrays.length; i++) {
            if (arrays[i].length > 0) minHeap.add(new Element(arrays[i][0], i, 0));
        }
        List<Integer> result = new ArrayList<>();
        while (!minHeap.isEmpty()) {
            Element curr = minHeap.poll();
            result.add(curr.val);
            if (curr.elemIdx + 1 < arrays[curr.arrIdx].length) {
                minHeap.add(new Element(arrays[curr.arrIdx][curr.elemIdx + 1], curr.arrIdx, curr.elemIdx + 1));
            }
        }
        return result;
    }
}

